/**
 * Uganda diagnosis catalog seed data.
 *
 * Two layers, both unique on key, description, and code:
 *
 *   1. UGANDA_PRIORITY_CONDITIONS - hand-curated presentations from the Uganda
 *      Clinical Guidelines / MoH priority conditions. These rank first in the
 *      diagnosis picker because they cover the bulk of real encounters.
 *   2. ICD10_CATEGORY_CATALOG - exactly one representative per three-character
 *      ICD-10 category, so every chapter stays reachable for coding without the
 *      catalog carrying near-duplicate rows.
 *
 * Deliberately absent: qualifier variants of a condition ("suspected X",
 * "severe X", "X in child", "X follow up"). They shared a single code with
 * their base term, so they added rows without adding meaning and buried the
 * canonical term in the picker. Acuity and certainty belong on the encounter
 * record, not in the diagnosis catalog.
 *
 * Layer 2 descriptions are ICD-10-CM rubric titles. ICD-10-CM is more granular
 * than WHO ICD-10 and the two are not interchangeable, so those rows carry the
 * CDC_ICD10_CM source rather than WHO_ICD10_2019.
 */

const { assertUniqueFields } = require('./catalog-validation');
const { UGANDA_CLINICAL_SOURCES } = require('./uganda-clinical-sources');

const PRIORITY_SOURCE = `${UGANDA_CLINICAL_SOURCES.UG_MOH_UCG_2023.id}+${UGANDA_CLINICAL_SOURCES.WHO_ICD10_2019.id}`;
const ICD10_SOURCE = UGANDA_CLINICAL_SOURCES.CDC_ICD10_CM.id;

const diagnosisTerm = (source, rankOffset) => ([key, description, code, category], index) => ({
  key,
  description,
  code,
  category,
  source,
  rank: rankOffset + index + 1,
});

